import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.products().getProduct(101);
Map<?, ?> product = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("product");
System.out.println(product.get("id") + " " + product.get("name") + " " + product.get("sku"));
System.out.println(product.get("base_price") + " " + product.get("available") + " " + product.get("version"));
Map<?, ?> pricingAndStock = (Map<?, ?>) product.get("product_pricing_and_stock");
System.out.println(pricingAndStock.get("available_stock"));

