import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.products().getProductStock(101);
Map<?, ?> stock = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) stock.get("locations")) {
    Map<?, ?> location = (Map<?, ?>) row;
    System.out.println(location.get("warehouse") + " " + location.get("warehouse_name") + " "
            + location.get("stock") + " " + location.get("is_default"));
}
System.out.println(stock.get("available_stock"));

