ApiResponse response = client.products().updateProductStock(101, Map.of("note", "Restock", "locations", List.of(
        Map.of("warehouse", 1, "stock", 10, "low_stock_level", 2, "is_default", true),
        Map.of("warehouse", 4, "stock", 30, "low_stock_level", 5, "is_default", false))));
Map<?, ?> stock = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) stock.get("locations")) {
    Map<?, ?> location = (Map<?, ?>) row;
    System.out.println(location.get("warehouse") + " " + location.get("stock") + " " + location.get("is_default"));
}
System.out.println(stock.get("available_stock"));
